import sys

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    N = data[0]
    a = data[1:1+N]

    if N == 1 and a[0] == 0:
        print("UP")
        return
    if N == 1 and a[0] == 15:
        print("DOWN")
        return
    if N == 1 and a[0] != 0 and a[0] != 15:
        print(-1)
        return

    if a[N-2] > a[N-1] and a[N-1] != 0:
        print("DOWN")
        return
    if a[N-2] < a[N-1] and a[N-1] != 15:
        print("UP")
        return
    if a[N-1] == 0:
        print("UP")
        return
    if a[N-1] == 15:
        print("DOWN")
        return

if __name__ == "__main__":
    main()

